int kth(Node* r, int k){                       // 1-indexed
    int L = sz(r->left);
    if (k == L + 1) return r->val;
    if (k <= L) return kth(r->left, k);
    return kth(r->right, k - L - 1);
}
int rankLess(Node* r, int x){                  // # keys < x
    if (!r) return 0;
    if (x <= r->val) return rankLess(r->left, x);
    return sz(r->left) + 1 + rankLess(r->right, x);
}

