def kth(r, k):                   # 1-indexed via size[] augmentation
    L = sz(r.left)
    if k == L + 1: return r.val
    return kth(r.left, k) if k <= L else kth(r.right, k - L - 1)

def rank_less(r, x):
    if not r: return 0
    if x <= r.val: return rank_less(r.left, x)
    return sz(r.left) + 1 + rank_less(r.right, x)

