int h(Node* r){ return r ? r->h : 0; }
int bf(Node* r){ return h(r->left) - h(r->right); }
Node* rotR(Node* y){ auto x=y->left; y->left=x->right; x->right=y; fix(y); fix(x); return x; }
Node* rotL(Node* x){ auto y=x->right; x->right=y->left; y->left=x; fix(x); fix(y); return y; }
// insert: recurse then on unwind:
int b = bf(node);
if (b > 1 && key < node->left->val)  return rotR(node);            // LL
if (b < -1 && key > node->right->val) return rotL(node);           // RR
if (b > 1) { node->left = rotL(node->left); return rotR(node); }   // LR
if (b < -1){ node->right = rotR(node->right); return rotL(node);}  // RL

