def rot_right(y):
    x = y.left; y.left = x.right; x.right = y; fix(y); fix(x); return x
def rot_left(x):
    y = x.right; x.right = y.left; y.left = x; fix(x); fix(y); return y
# insert unwind: bf = h(L)-h(R)
# LL: rotR | RR: rotL | LR: rotL(left)+rotR | RL: rotR(right)+rotL
